  f=new Fixture(job(4,"text","text"));f.control("pause");f.tick();check(f.net.submissions==0&&f.j().getString("task").equals("paused"),"pause before submission");f.control("cancel");f.tick();check(f.j().getString("task").equals("cancelled"),"cancel paused batch");
  f=new Fixture(job(4,"text","text"));f.net.failPostAfterAccept=true;f.tick();check(f.j().getBoolean("submissionUncertain"),"uncertain submission persisted");f.restart();f.tick();check(f.net.submissions==1&&f.j().getString("promptId").equals("prompt-1"),"lost HTTP response recovers by metadata");
  f=new Fixture(job(4,"text","text"));f.net.failPostAfterAccept=true;f.tick();f.net.done.add("prompt-1");f.restart();f.tick();check(f.net.submissions==1&&f.j().getJSONObject("batch").getInt("completed")==1,"recovery finds already completed history");
