  f=new Fixture(job(4,"text","text"));f.tick();f.net.offline=true;f.tick();check(!BatchStore.terminal(f.j().getString("task")),"network loss never automatically pauses/cancels");f.restart();f.net.offline=false;f.net.done.add("prompt-1");f.tick();f.tick();check(f.net.submissions==2,"connection recovery automatically resumes batch");
